/// <summary>
/// Updatejob for LedgerJournalTrans, VendInvoiceJour , VendInvoiceInfoTable to populate METALMSupplierVolumetricRebateNumber on historical records
/// MPJ_21593 SVR document DCP 13/05/2022
/// </summary>
class METALMSupplierVolumetricRebate_Update
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        METALMSupplierVolumetricRebate_Update instance = new METALMSupplierVolumetricRebate_Update();

        instance.run();
    }

    /// <summary>
    /// Update LedgerJournalTrans, VendInvoiceJour , VendInvoiceInfoTable
    /// </summary>
    public void run()
    {
        this.SVRUpdate();
        this.RDAUpdate();

        Info("Update process complete");

    }

    /// <summary>
    /// Update LedgerJournalTrans, VendInvoiceJour
    /// </summary>
    public void SVRUpdate()
    {
        METALMSupplierVolumetricRebateHeader    header;
        LedgerJournalTrans                      ledgerJournalTrans;
        Counter                                 recordCount;
        VendInvoiceJour                         vendInvoiceJour;

        //SVR -> LedgerJournalTrans ->VendInvoiceJour
        recordCount = 0;

        ttsbegin;
        while select forUpdate ledgerJournalTrans
            where   ledgerJournalTrans.AccountType == LedgerJournalACType::Vend
            &&      ledgerJournalTrans.METALMSupplierVolumetricRebateNumber == ""

            join  number
            from    header
            where   header.InvoiceId        == ledgerJournalTrans.Invoice
            &&      header.DocumentDate     == ledgerJournalTrans.DocumentDate
            &&      header.TransactionDate  == ledgerJournalTrans.TransDate
            &&      header.Status           == METALMSupplierVolumetricRebateStatus::Processed
            &&      header.Type             == METALMSupplierVolumetricRebateType::SVR
        {
            ledgerJournalTrans.reread(); //some records selected twice
            ledgerJournalTrans.METALMSupplierVolumetricRebateNumber = header.Number;
            ledgerJournalTrans.doUpdate();

            recordCount++;
        }

        ttscommit;
        Info(strFmt("%1 SVR -> LedgerJournalTrans updated",recordCount));


        recordCount = 0;

        ttsbegin;
        while select forUpdate vendInvoiceJour
            where   vendInvoiceJour.METALMSupplierVolumetricRebateNumber == ""

            join  number
            from    header
            where   header.InvoiceId        == vendInvoiceJour.InvoiceId
            &&      header.DocumentDate     == vendInvoiceJour.DocumentDate
            &&      header.Status           == METALMSupplierVolumetricRebateStatus::Processed
            &&      header.Type             == METALMSupplierVolumetricRebateType::SVR
        {
            vendInvoiceJour.reread(); //some records selected twice
            vendInvoiceJour.METALMSupplierVolumetricRebateNumber = header.Number;
            vendInvoiceJour.doUpdate();

            recordCount++;
        }

        ttscommit;
        Info(strFmt("%1 SVR -> vendInvoiceJour updated",recordCount));

    }

    /// <summary>
    /// Update VendInvoiceJour , VendInvoiceInfoTable
    /// </summary>
    public void RDAUpdate()
    {
        METALMSupplierVolumetricRebateHeader    header;
        
        Counter                                 recordCount;
        VendInvoiceInfoTable                    vendInvoiceInfoTable;
        VendInvoiceJour                         vendInvoiceJour;

        //RDA -> VendInvoiceInfoTable -> VendInvoiceJour
        recordCount = 0;
        ttsbegin;

        while select forupdate VendInvoiceInfoTable
            where   VendInvoiceInfoTable.METALMSupplierVolumetricRebateNumber == ""

            join	header
            where   header.INVOICEID        == VendInvoiceInfoTable.NUM
            &&		header.VENDORACCOUNT    == VendInvoiceInfoTable.INVOICEACCOUNT
            &&		header.DOCUMENTDATE     == VendInvoiceInfoTable.DOCUMENTDATE
            &&		header.TRANSACTIONDATE  == VendInvoiceInfoTable.TRANSDATE
            &&		header.STATUS           == METALMSupplierVolumetricRebateStatus::Processed
            &&		header.Type             == METALMSupplierVolumetricRebateType::RDA
        {
            VendInvoiceInfoTable.reread(); //some records selected twice
            VendInvoiceInfoTable.METALMSupplierVolumetricRebateNumber = header.Number;
            VendInvoiceInfoTable.doUpdate();

            recordCount++;
        }
        
        ttscommit;

        Info(strFmt("%1 RDA -> VendInvoiceInfoTable updated",recordCount));

        recordCount = 0;

        ttsbegin;
        while select forUpdate vendInvoiceJour
            where   vendInvoiceJour.METALMSupplierVolumetricRebateNumber == ""

            join  number
            from    header
            where   header.InvoiceId        == vendInvoiceJour.InvoiceId
            &&      header.DocumentDate     == vendInvoiceJour.DocumentDate
            &&      header.Status           == METALMSupplierVolumetricRebateStatus::Processed
            &&      header.Type             == METALMSupplierVolumetricRebateType::RDA
        {
            vendInvoiceJour.reread(); //some records selected twice
            vendInvoiceJour.METALMSupplierVolumetricRebateNumber = header.Number;
            vendInvoiceJour.doUpdate();

            recordCount++;
        }

        ttscommit;
        Info(strFmt("%1 RDA -> vendInvoiceJour updated",recordCount));

    }
